"""matplotlib.backends.backend_nbagg — nbagg backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_nbagg import
FigureCanvasNbagg`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasNbagg = _make_canvas('FigureCanvasNbagg', 'png')
FigureManagerNbagg = _make_manager('FigureManagerNbagg')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasNbagg
FigureManager = FigureManagerNbagg

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendNbagg', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show


